<script setup lang="ts">
import { computed, onMounted, ref, watch } from 'vue'
import { AlertTriangle, Check, CircleStop, Clock3, DatabaseBackup, Play, ShieldCheck, Sparkles, Wrench } from 'lucide-vue-next'
import { apiRequest } from '../lib/api'

const props=defineProps<{serverId:string}>()
interface Task { id:string; server_id:string; title:string; kind:string; status:string; progress:number; created_at:string; risk:string }
const tasks=ref<Task[]>([]), loading=ref(false), notice=ref('')
const visibleTasks=computed(()=>tasks.value.filter(task=>task.server_id===props.serverId||task.server_id==='all'))
const pending=computed(()=>visibleTasks.value.filter(task=>task.status==='queued'&&task.risk!=='low').length)
const running=computed(()=>visibleTasks.value.filter(task=>task.status==='running').length)
async function load(){try{const data=await apiRequest<{tasks:Task[]}>('/api/automation');tasks.value=data.tasks}catch(error){notice.value=String(error)}}
async function create(kind:string,title:string,risk:string){loading.value=true;try{await apiRequest<Task>('/api/automation/tasks',{method:'POST',body:JSON.stringify({server_id:props.serverId,title,kind,risk})});notice.value=risk==='low'?'任务已自动开始':'任务已创建，等待批准';await load()}finally{loading.value=false}}
async function act(task:Task,action:'approve'|'cancel'){loading.value=true;try{await apiRequest<Task>('/api/tasks/'+task.id+'/'+action,{method:'POST'});await load()}finally{loading.value=false}}
watch(()=>props.serverId,load);onMounted(load)
</script>

<template>
  <div class="module-scroll">
    <section class="module-hero"><div><span><Sparkles/></span><p><small>AI AUTOMATION</small><b>自动化与安全审批</b><em>低风险任务自动执行，中高风险操作需要人工批准。</em></p></div><i><ShieldCheck/>审计保护已开启</i></section>
    <div class="stats"><article><span class="mint"><Play/></span><p><small>执行中</small><b>{{running}}</b><em>实时同步</em></p></article><article><span class="amber"><AlertTriangle/></span><p><small>等待批准</small><b>{{pending}}</b><em>需人工确认</em></p></article><article><span class="violet"><Clock3/></span><p><small>任务总数</small><b>{{visibleTasks.length}}</b><em>当前服务器</em></p></article></div>
    <section class="quick-card"><header><div><small>快捷自动化</small><b>创建运维任务</b></div><span v-if="notice">{{notice}}</span></header><div class="quick-grid"><button :disabled="loading" @click="create('diagnostic','分析最新日志并生成修复方案','medium')"><Wrench/><span><b>智能诊断</b><small>分析报错并生成修复计划</small></span><em>中风险</em></button><button :disabled="loading" @click="create('backup','创建世界与配置快照','low')"><DatabaseBackup/><span><b>立即备份</b><small>创建可回滚的完整快照</small></span><em class="low">低风险</em></button><button :disabled="loading" @click="create('economy','生成经济调控执行方案','high')"><Sparkles/><span><b>经济调控</b><small>分析物价并提出参数调整</small></span><em class="high">高风险</em></button></div></section>
    <section class="task-card"><header><div><small>任务队列</small><b>执行与审批记录</b></div></header><div v-if="!visibleTasks.length" class="empty-state">暂无自动化任务</div><article v-for="task in visibleTasks" :key="task.id"><span class="task-icon" :class="task.status"><Check v-if="task.status==='completed'"/><Play v-else-if="task.status==='running'"/><Clock3 v-else/></span><div class="task-main"><div><b>{{task.title}}</b><i :class="task.risk">{{task.risk==='high'?'高风险':task.risk==='medium'?'中风险':'低风险'}}</i></div><small>{{task.kind}} · {{new Date(task.created_at).toLocaleString('zh-CN')}}</small><div class="bar"><i :style="{width:task.progress+'%'}"/></div></div><em class="task-status">{{task.status==='queued'?'等待批准':task.status==='running'?'执行中':task.status==='cancelled'?'已取消':'已完成'}}</em><div v-if="task.status==='queued'" class="actions"><button class="approve" @click="act(task,'approve')"><Check/>批准</button><button @click="act(task,'cancel')"><CircleStop/>取消</button></div></article></section>
  </div>
</template>

<style scoped>
