d rgba(255,255,255,.08);border-radius:6px;color:#8793a0;background:#171d24;font-size:7px}.actions button.approve{border-color:rgba(50,213,176,.17);color:#79dac3;background:rgba(50,213,176,.06)}.actions svg{width:11px}.empty-state{padding:30px;text-align:center;color:#596572;font-size:9px}@media(max-width:900px){.stats,.quick-grid{grid-template-columns:1fr}.task-status{display:none}}
</style>
